-- Run in the Supabase SQL editor before enabling registration; safe to rerun.
-- Passwords are managed by Supabase Auth, never stored in this table.
begin;
create table if not exists public."User" (
    "UserID" bigint generated by default as identity primary key,
    "AuthUserId" uuid,
    "Email" varchar(254) not null,
    "UserName" varchar(100) not null check (length(trim("UserName")) > 0),
    "createdDate" timestamptz not null default now()
);
-- Retain existing UserID, UserName, createdDate, and legacy Password columns.
alter table public."User" add column if not exists "AuthUserId" uuid;
create unique index if not exists "User_AuthUserId_unique" on public."User" ("AuthUserId");
do $$
begin
    if not exists (select 1 from pg_constraint where conname = 'User_AuthUserId_fkey' and conrelid = 'public."User"'::regclass) then
        alter table public."User" add constraint "User_AuthUserId_fkey"
            foreign key ("AuthUserId") references auth.users(id) on delete cascade;
    end if;
end;
$$;
alter table public."User" enable row level security;
revoke all on public."User" from anon, authenticated;

create or replace function public.sync_wedding_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
    if new.email is null then return new; end if;
    insert into public."User" ("AuthUserId", "Email", "UserName")
    values (new.id, new.email, coalesce(nullif(left(trim(new.raw_user_meta_data ->> 'username'), 100), ''), split_part(new.email, '@', 1)))
    on conflict ("AuthUserId") do update set "Email" = excluded."Email";
    return new;
end;
$$;
revoke all on function public.sync_wedding_user() from public, anon, authenticated;
drop trigger if exists wedding_user_created on auth.users;
create trigger wedding_user_created after insert or update of email on auth.users
for each row execute function public.sync_wedding_user();

-- Link existing legacy profiles by email before inserting missing profiles.
update public."User" p set "AuthUserId" = a.id
from auth.users a where p."AuthUserId" is null and lower(p."Email") = lower(a.email);
insert into public."User" ("AuthUserId", "Email", "UserName")
select id, email, coalesce(nullif(left(trim(raw_user_meta_data ->> 'username'), 100), ''), split_part(email, '@', 1))
from auth.users where email is not null
on conflict ("AuthUserId") do update set "Email" = excluded."Email";
commit;
